  (* [comment removed for export] *)
  Lemma rbB_final : forall m ns ns' (p pp gpv gpl : Z) (x1 t0 t1 t2 a1 a2 a3 a4 a5 a7 t3 t4 t5 t6 : word),
    rb_ctx m ns ->
    (rb_final ns h p pp gpv gpl ≫= (λ ns2, rb_end ns2 h)) = Some ns' ->
    0 <= p < 2^64 -> 0 <= pp < 2^64 -> 0 <= gpv < 2^64 -> 0 <= gpl < 2^64 ->
    evt bsegs (POST ns')
      (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2 (Z_to_bv 64 h) (Z_to_bv 64 p)
               (Z_to_bv 64 pp) a1 a2 a3 a4 a5 (Z_to_bv 64 gpl) a7
               (Z_to_bv 64 gpv) (Z_to_bv 64 2147450880) s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
