Definition rebal_stmt : Prop := forall (h p : Z) (ns ns' : NS) (fuel : nat) (lo : Z) (X : list Z)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  ANSR m ns X -> 0 <= h < 2^64 ->
  rebalance_after_insertion fuel ns h p = Some ns' ->
  stk bsegs m lo (bv_unsigned sp) -> aceil <= lo -> lo + REBAL_STACK <= bv_unsigned sp ->      (* [comment removed for export] *)
  mem_inv bsegs m ->
  ACONST m ->                                                                                  (* [comment removed for export] *)
  cols_ok [p] ns ->                                                                            (* [comment removed for export] *)
  evt bsegs (rebal_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc ns' lo X m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz h) (wz p) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_RB_REBALANCE) fc None m (seg_rom bsegs)).

